def sh(cmd, timeout):
    return subprocess.run(cmd, shell=True, capture_output=True, stdin=subprocess.DEVNULL, timeout=timeout)


def _free_mb(path=LLM):
    st = os.statvfs(path)
    return st.f_bavail * st.f_frsize / (1024 * 1024)


def _remote_mb(model):
    """Content-Length of the store's copy in MB, or None. Sizes the disk guard before pulling.
    urllib, not curl: Termux's curl is linker-broken on these tablets (missing SSL_set_quic symbol)."""
    try:
        req = urllib.request.Request("%s/%s.gguf" % (STAGE_URL, model), method="HEAD")
        with urllib.request.urlopen(req, timeout=20) as r:
            cl = r.headers.get("Content-Length")
            return int(cl) / (1024 * 1024) if cl else None
    except Exception:
        return None


def _remote_path_mb(remote_path):
    """Content length for an arbitrary artifact under the central HTTP store."""
    try:
        req = urllib.request.Request("%s/%s" % (STAGE_URL, remote_path), method="HEAD")
        with urllib.request.urlopen(req, timeout=20) as r:
            cl = r.headers.get("Content-Length")
            return int(cl) / (1024 * 1024) if cl else None
    except Exception:
        return None


def _download_artifact(remote_path, local_path, executable=False, pulled_marker=False):
    """Download one immutable artifact atomically. Returns None on success or a reason string."""
    if os.path.exists(local_path):
        if executable:
            os.chmod(local_path, 0o755)
        return None
    os.makedirs(os.path.dirname(local_path), exist_ok=True)
    tmp = local_path + ".part"
    try:
        with urllib.request.urlopen("%s/%s" % (STAGE_URL, remote_path), timeout=1200) as r, \
                open(tmp, "wb") as f:
            shutil.copyfileobj(r, f, 1024 * 1024)
        if os.path.getsize(tmp) <= 0:
            raise OSError("empty artifact")
        os.replace(tmp, local_path)
        if executable:
            os.chmod(local_path, 0o755)
        if pulled_marker:
            open(local_path + ".pulled", "w").close()
        return None
    except Exception:
        try:
            os.remove(tmp)
        except OSError:
            pass
        return "stage-transfer-failed"


def _evict_pulled(need_mb):
    """Free space by deleting ONLY models THIS payload pulled (marked .pulled), largest first.
    Models already on the tablet are never touched -- they carry no .pulled marker."""
    pulled = [f for f in os.listdir(LLM)
              if f.endswith(".gguf") and os.path.exists(os.path.join(LLM, f + ".pulled"))]
    pulled.sort(key=lambda f: os.path.getsize(os.path.join(LLM, f)), reverse=True)
    for f in pulled:
        if _free_mb() >= need_mb:
            break
        for x in (f, f + ".pulled"):
            try:
                os.remove(os.path.join(LLM, x))
            except OSError:
                pass


def stage_model(model):
    """Return the gguf path if present, else pull it from the central store. On a small-disk node,
    evict previously-pulled models first. Returns (path, None) on success or (None, reason) where
    reason distinguishes a storage non-fit from a transfer failure -- both are real matrix signals."""
    path = os.path.join(LLM, model + ".gguf")
    if os.path.exists(path):
        return path, None
    if not STAGE_URL:
        return None, "model-not-staged"
    need = _remote_mb(model)
    if need is None:
        return None, "model-not-in-store"
    if _free_mb() < need + KEEP_FREE_MB:
        _evict_pulled(need + KEEP_FREE_MB)
    if _free_mb() < need + KEEP_FREE_MB:
        return None, "model-too-big-for-node"          # fit:false by storage
    tmp = path + ".part"
    try:
        with urllib.request.urlopen("%s/%s.gguf" % (STAGE_URL, model), timeout=1200) as r, \
                open(tmp, "wb") as f:
            shutil.copyfileobj(r, f, 1024 * 1024)
    except Exception:
        try:
            os.remove(tmp)
        except OSError:
            pass
        return None, "stage-transfer-failed"
    if os.path.exists(tmp) and os.path.getsize(tmp) > 1_000_000:
        os.replace(tmp, path)
        open(path + ".pulled", "w").close()            # mark evictable; never evicts a model that was on the tablet before
        return path, None
    try:
        os.remove(tmp)
    except OSError:
        pass
    return None, "stage-transfer-failed"


def _run_llama(model, prompt, grammar=None, n=160):
    """Run llama-cli once with the prompt staged to a file; returns (stdout_text, wall_s) or (None, wall)."""
    with open(os.path.join(LLM, "_g_prompt.txt"), "w", encoding="utf-8") as f:
        f.write(prompt)
    g = ""
    if grammar:
        with open(os.path.join(LLM, "_g.gbnf"), "w", encoding="utf-8") as f:
            f.write(grammar)
        g = "--grammar-file _g.gbnf"
    cmd = ("cd %s && LD_LIBRARY_PATH=. ./llama-cli -m %s.gguf -f _g_prompt.txt "
           "-st --no-display-prompt --temp 0 --seed 1 -n %d -c 2048 -t 8 %s"
           % (LLM, model, n, g))
    t0 = time.time()
    try:
        r = sh(cmd, timeout=400)
    except subprocess.TimeoutExpired:
        return None, round(time.time() - t0, 1)
    return r.stdout.decode(errors="replace"), round(time.time() - t0, 1)


def isolate(out, prompt):
    for m in ("[ Prompt:", "\nExiting", "\n> /", "\n> \n"):
        i = out.find(m)
        if i != -1:
            out = out[:i]
    plines = [l.rstrip() for l in prompt.splitlines() if l.strip()]
    if plines:
        idx = out.rfind(plines[-1])
        if idx != -1:
            out = out[idx + len(plines[-1]):]
    return out.strip()


def extract_json(ans):
    s = ans.find("{")
    if s == -1:
        return None
    d = 0
    for i in range(s, len(ans)):
        if ans[i] == "{":
            d += 1
        elif ans[i] == "}":
            d -= 1
            if d == 0:
                try:
                    return json.loads(ans[s:i + 1])
                except Exception:
                    return None
    return None


def _norm(v):
    return v.strip().lower() if isinstance(v, str) else v


def _args_ok(got, gold):
    if gold is None:
        return None
    if not isinstance(got, dict):
        return False
    for k, v in gold.items():
        g = got.get(k, got.get(k.lower()))
        if g is None:
            return False
        if _norm(g) != _norm(v) and str(_norm(g)) != str(_norm(v)):
            return False
    return True


def run_tool_cell(model, taskid):
    req, gold_tool, gold_args = TOOL_TASKS[taskid]
    prompt = PREAMBLE.format(req=req)
    out, wall = _run_llama(model, prompt, grammar=GBNF)
    if out is None:
        return {"ran": False, "reason": "timeout", "ok": None, "wall_s": wall}
    ans = isolate(out, prompt)
    parsed = extract_json(ans)
    tool_ok = bool(parsed and parsed.get("tool") == gold_tool)
    args_ok = _args_ok((parsed or {}).get("arguments"), gold_args)
    return {"ran": True, "ok": tool_ok, "tool_ok": tool_ok, "args_ok": args_ok, "wall_s": wall,
            "tool": (parsed or {}).get("tool"), "answer": ans[:160]}


def run_chat_cell(model, taskid):
    q, gold = CHAT_TASKS[taskid]
    prompt = q + "\n"
    out, wall = _run_llama(model, prompt, n=120)
    if out is None:
        return {"ran": False, "reason": "timeout", "ok": None, "wall_s": wall}
    ans = isolate(out, prompt)
    hit = re.search(r"\b" + re.escape(gold) + r"\b", ans, re.I) is not None
    return {"ran": True, "ok": hit, "wall_s": wall, "gold": gold, "answer": ans[:200]}


def extract_code(ans):
    m = re.search(r"```(?:python)?\s*(.*?)```", ans, re.S | re.I)
    if m:
        return m.group(1).strip()
    return ans.strip()


def run_coding_cell(model, taskid):
    prompt, funcname, test = CODE_TASKS[taskid]
    out, wall = _run_llama(model, prompt, n=256)
    if out is None:
        return {"ran": False, "reason": "timeout", "ok": None, "wall_s": wall}
    ans = isolate(out, prompt)
    code = extract_code(ans)
    if funcname not in code:
        return {"ran": True, "ok": False, "wall_s": wall, "reason": "no-func", "answer": ans[:200]}
    prog = code + "\n" + test + "\nprint('CODE_OK')\n"
    p = os.path.join(LLM, "_g_code.py")
    with open(p, "w", encoding="utf-8") as f:
        f.write(prog)
    try:
        r = sh("cd %s && python _g_code.py" % LLM, timeout=30)
        ok = r.returncode == 0 and b"CODE_OK" in r.stdout
        err = "" if ok else (r.stderr.decode(errors="replace").strip().splitlines() or [""])[-1][:120]
    except subprocess.TimeoutExpired:
        ok, err = False, "exec-timeout"
    return {"ran": True, "ok": ok, "wall_s": wall, "err": err, "answer": ans[:200]}


def _mem_total_mb():
    try:
        with open("/proc/meminfo", encoding="ascii") as f:
            for line in f:
                if line.startswith("MemTotal:"):
                    return int(line.split()[1]) / 1024.0
    except Exception:
        pass
    return None


def _vlm_score(ans, expected, match):
    toks = re.sub(r"[^a-z0-9 ]", " ", ans.lower()).split()
    joined = " ".join(toks)
    if match == "word":
        return expected in toks
    return expected in joined


def stage_vlm_bundle(model, taskid):
    """Stage model, mmproj, mtmd runtime, and the cell image.

    The 2B bundles are known to OOM sub-A tablets. Record that arithmetic exclusion before
    loading: every matrix cell still lands, but an obviously impossible lane is not destabilized.
    """
    mmproj = VLM_MM_PROJ.get(model)
    if not mmproj:
        return None, None, None, "unknown-vlm-model"
    img = _VLM_ALL[taskid][0]
    artifacts = [
        (model + ".gguf", os.path.join(LLM, model + ".gguf"), False, True),
        (mmproj + ".gguf", os.path.join(LLM, mmproj + ".gguf"), False, True),
        ("runtime/llama-mtmd-cli", os.path.join(LLM, "llama-mtmd-cli"), True, False),
        ("vlm_set/" + img, os.path.expanduser("~/vlm_set/" + img), False, False),
    ]
    sizes = {}
    for remote, local, _exe, _mark in artifacts:
        if not os.path.exists(local):
            sizes[remote] = _remote_path_mb(remote)
            if sizes[remote] is None:
                return None, None, None, "artifact-not-in-store"

    model_mb = _remote_path_mb(model + ".gguf")
    mmproj_mb = _remote_path_mb(mmproj + ".gguf")
    mem_total = _mem_total_mb()
    if model_mb is None or mmproj_mb is None:
        return None, None, None, "artifact-not-in-store"
    if mem_total is not None and model_mb + mmproj_mb + VLM_RAM_OVERHEAD_MB > mem_total:
        return None, None, None, "model-too-big-for-node-ram"

    disk_need = sum(v for v in sizes.values() if v is not None)
    if _free_mb() < disk_need + KEEP_FREE_MB:
        _evict_pulled(disk_need + KEEP_FREE_MB)
    if _free_mb() < disk_need + KEEP_FREE_MB:
        return None, None, None, "model-too-big-for-node"

    for remote, local, executable, mark in artifacts:
        why = _download_artifact(remote, local, executable=executable, pulled_marker=mark)
        if why:
            return None, None, None, why
    return (os.path.join(LLM, model + ".gguf"),
            os.path.join(LLM, mmproj + ".gguf"),
            os.path.expanduser("~/vlm_set/" + img), None)


# ---------------------- Answer boundary (generated from cli_answer.py - measured; see its docstring)
LLAMA_CLI_ECHO_LIMIT = 500
LLAMA_CLI_TRUNCATED = ' ... (truncated)\n'
LLAMA_CLI_STATS = '\n\n[ Prompt:'


def llama_cli_answer(stdout, prompt):
    end = stdout.rfind(LLAMA_CLI_STATS)
    if end < 0:
        return None, "answer_boundary:stats_line_missing"
    echo = "\n> " + prompt[:LLAMA_CLI_ECHO_LIMIT]
    n = stdout.count(echo, 0, end)
    if n != 1:
        return None, "answer_boundary:prompt_echo_found_%d_times" % n
    i = stdout.find(echo) + len(echo)
    tail = LLAMA_CLI_TRUNCATED if len(prompt) > LLAMA_CLI_ECHO_LIMIT else "\n"
    if not stdout.startswith(tail, i):
        return None, "answer_boundary:prompt_echo_end_unrecognised"
    return stdout[i + len(tail):end].strip("\n"), ""


def mtmd_answer(stdout):
    answer = stdout.strip()
    if not answer:
        return None, "answer_boundary:empty_stdout"
    return answer, ""



def run_vlm_cell(model, taskid, seed=1):
    model_path, mmproj_path, image_path, why = stage_vlm_bundle(model, taskid)
    if why:
        return {"ran": False, "reason": why, "ok": None}
    _img, question, expected, match, category = _VLM_ALL[taskid]
    cmd = ("cd %s && LD_LIBRARY_PATH=. ./llama-mtmd-cli -m %s -mm %s --image %s "
           "-p %s -n 32 --temp %s --seed %d -c 2048 -t 8" %
           (shlex.quote(LLM), shlex.quote(model_path), shlex.quote(mmproj_path),
            shlex.quote(image_path), shlex.quote(question), VLM_TEMPERATURE, seed))
    t0 = time.time()
    try:
        r = sh(cmd, timeout=600)
    except subprocess.TimeoutExpired:
        return {"ran": False, "reason": "timeout", "ok": None,
                "wall_s": round(time.time() - t0, 1), "category": category}
    wall = round(time.time() - t0, 1)
    out = r.stdout.decode(errors="replace").strip()
    err = r.stderr.decode(errors="replace")
    if r.returncode != 0:
        return {"ran": False, "reason": "mtmd-exit-%d" % r.returncode, "ok": None,
                "wall_s": wall, "category": category, "err": err[-160:]}
    ans, aerr = mtmd_answer(out)
    if aerr:
        return {"ran": False, "reason": aerr, "ok": None, "wall_s": wall, "category": category, "raw_stdout": out}
    enc_ms = sum(int(m) for m in re.findall(r"encoding done in (\d+) ms", err))
    tps = re.findall(r"([\d.]+) tokens per second", err)
    return {"ran": True, "ok": _vlm_score(ans, expected, match), "wall_s": wall, "temperature": VLM_TEMPERATURE,
            "enc_s": round(enc_ms / 1000.0, 1), "gen_tps": (float(tps[-1]) if tps else None),
            "category": category, "gold": expected, "answer": ans}


DIVISIONS = {"tool": (TOOL_TASKS, run_tool_cell),
             "chat": (CHAT_TASKS, run_chat_cell),
             "coding": (CODE_TASKS, run_coding_cell),
             "vlm": (VLM_TASKS, run_vlm_cell)}


def main():
    items_file, out_file = sys.argv[1], sys.argv[2]
    with open(items_file, encoding="utf-8") as f:
        cells = [l.strip() for l in f if l.strip()]
    rows = []
    for cell in cells:
        lane, marker, body = cell.partition("~")
        payload_cell = body if marker and lane in {"A", "B", "C", "sam"} else cell
        parts = (payload_cell.split("~") + ["", "", "", "", "", ""])[:6]
        arm, model, division, taskid, replicate_text, seed_text = parts
        row = {"item": cell, "arm": arm, "model": model, "division": division,
               "task": taskid, "ran": False, "ok": False}
        try:
            replicate, seed = int(replicate_text), int(seed_text)
            row.update({"replicate": replicate, "seed": seed})
            if replicate < 0 or seed != replicate + 1:
                row.update({"reason": "bad-replicate-seed"})
            elif model not in VLM_MODELS_ALLOWED or division != "vlm":
                row.update({"reason": "wrong-model-or-division"})
            elif arm == "vlm-hard" and taskid in VLM_TASKS:
                row.update(run_vlm_cell(model, taskid, seed))
            elif arm == "control" and taskid == "control_vlm":
                result = run_vlm_cell(model, "n_number", seed)
                row.update(result)
                if result.get("ok"):
                    row["control_result"] = VLM_CONTROL_SENTINEL
            else:
                row.update({"reason": "unknown-cell"})
        except Exception as e:
            row.update({"ran": False, "ok": False,
                        "reason": "payload-error:%s" % type(e).__name__})
        rows.append(row)
    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(rows, f)


if __name__ == "__main__":
    main()
